@nkl.function
async def trial(number: int) -> ColourReport:
    turn = TURNS[number]
    first = FIRSTS[number]
    hues = HUES[number]
    cued = CUED[number]
    places = [
        place(first + 90.0 * k) for k in range(ITEMS)
    ]
    at = places[cued]
    true = hues[cued]

    await nkl.show(
        nkl.constant(
            Layer(graphics=[field(), fixation()])
        )
    )
    await nkl.sleep(FIXATION)
    flash = piecewise(
        [
            (0.0, 0.0),
            (RAMP, 1.0),
            (EXPOSURE - RAMP, 1.0),
            (EXPOSURE, 0.0),
        ],
        between="smoothstep",
    )
    squares: list[Graphic] = [
        square(places[k], hue_of(hues[k]))
        for k in range(ITEMS)
    ]
    await nkl.show(
        nkl.constant(
            Layer(
                graphics=[
                    field(),
                    Opacity(
                        Layer(graphics=squares), flash
                    ),
                ]
            )
        )
    )
    await nkl.sleep(EXPOSURE)
    await nkl.show(
        nkl.constant(
            Layer(graphics=[field(), fixation()])
        )
    )
    await nkl.sleep(DELAY)

    arrive = piecewise(
        [(0.0, 0.0), (ARRIVE, 1.0)],
        between="smoothstep",
    )
    wheel = Rotate(RING, turn)

    def chosen(
        pointer: nkl.pointer.PointerInput,
    ) -> Graphic:
        graphics: list[Graphic] = [
            field(),
            Opacity(wheel, arrive),
        ]
        if on_ring(pointer.location):
            graphics.append(
                square(
                    at,
                    hue_of(
                        angle_of(pointer.location)
                        - turn
                    ),
                )
            )
        graphics.append(outline(at))
        graphics.append(fixation())
        return Layer(graphics=graphics)

    await nkl.show(
        nkl.map(chosen, nkl.pointer.signal())
    )
    click = await nkl.race(
        nkl.next(
            nkl.filter(choosing, nkl.pointer.stream())
        ),
        show_cursor(),
    )
    reported = folded(angle_of(click.location) - turn)

    settle = piecewise(
        [(0.0, 0.0), (REVEAL, 1.0)],
        between="smoothstep",
    )
    leave = piecewise(
        [
            (0.0, 1.0),
            (REVEAL + HOLD, 1.0),
            (REVEAL + HOLD + FADE, 0.0),
        ],
        between="smoothstep",
    )
    await nkl.show(
        nkl.constant(
            Layer(
                graphics=[
                    field(),
                    Opacity(
                        Layer(
                            graphics=[
                                wheel,
                                square(
                                    at, hue_of(reported)
                                ),
                                outline(at),
                                Opacity(
                                    tick(true + turn),
                                    settle,
                                ),
                            ]
                        ),
                        leave,
                    ),
                    fixation(),
                ]
            )
        )
    )
    await nkl.sleep(REVEAL + HOLD + FADE + PAUSE)
    return ColourReport(
        true_hue=true,
        reported_hue=reported,
        error=wrapped(reported - true),
    )

@nkl.function
async def trial(index: int) -> Choice:
    shown = await nkl.time()
    chosen = await nkl.race(
        choose(index), time_limit(), hover()
    )
    pressed = await nkl.time()
    if chosen >= 0:
        await nkl.show(
            nkl.constant(
                settled(index, chosen, pressed - shown)
            )
        )
        await nkl.sleep(SETTLE + HOLD + FADE + 160.0)
    else:
        await nkl.show(nkl.constant(unanswered(index)))
        await nkl.sleep(FADE + 160.0)
    return Choice(
        item=index + 1,
        rule=RULES[index],
        chosen=chosen,
        answer=ANSWERS[index],
        correct=chosen == ANSWERS[index],
        milliseconds=pressed - shown,
    )

@nkl.function
async def sketch() -> int:
    strokes: list[list[Location]] = []
    down = False
    while True:
        await nkl.show(nkl.constant(page(strokes)))
        pointer = await nkl.next(nkl.pointer.stream())
        if (
            pointer.down
            and not down
            and on_button(pointer)
        ):
            break
        if pointer.down and down:
            last = len(strokes) - 1
            strokes = strokes[:last] + [
                strokes[last] + [pointer.location]
            ]
        elif pointer.down:
            strokes = strokes + [[pointer.location]]
        down = pointer.down
    return len(strokes)
